import sys
sys.setrecursionlimit(10000)

def placements(n):
    res = []
    for r in range(n-1):
        for c in range(n-1):
            sq = [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            for skip in sq:
                res.append(tuple(x for x in sq if x != skip))
    return res

def tileable(n):
    if n*n % 3:
        return False
    pl = placements(n)
    by = {}
    for p in pl:
        for cell in p:
            by.setdefault(cell, []).append(p)
    filled = [[False]*n for _ in range(n)]
    def solve():
        for r in range(n):
            for c in range(n):
                if not filled[r][c]:
                    for p in by.get((r,c), []):
                        if all(not filled[a][b] for a,b in p):
                            for a,b in p: filled[a][b] = True
                            if solve(): return True
                            for a,b in p: filled[a][b] = False
                    return False
        return True
    return solve()

results = {}
for n in range(1, 7):
    results[n] = tileable(n)
    print(f"n={n}: area={n*n}, area%3={n*n%3}, tileable by L-trominoes: {results[n]}")

failing = [n for n, ok in results.items() if not ok]
print("Squares (n<=6) that cannot be tiled:", failing)
